# strftime format code to regex pattern mapping
# Supports C standard datetime format codes with flexible digit handling
_DT_FORMAT_CODES = {
    '%Y': r'(\d{4})',
    '%y': r'(\d{2})',
    '%m': r'(\d{1,2})',       # flexible single-digit months
    '%d': r'(\d{1,2})',       # flexible single-digit days
    '%H': r'(\d{2})',
    '%I': r'(\d{2})',
    '%M': r'(\d{2})',
    '%S': r'(\d{2})',
    '%f': r'(\d+)',           # variable digits for microseconds
    '%z': r'([+-]\d{1,2}:?\d{2}|[+-]\d{4})',  # variable-length tz with optional colon
    '%Z': r'([A-Za-z]+)',
    '%a': r'(\w{3})',
    '%A': r'(\w+)',
    '%b': r'(\w{3})',
    '%B': r'(\w+)',
    '%p': r'(AM|PM)',
    '%%': r'%',
}


def dt_format_to_regex(datetime_format):
    """Convert a strftime-style datetime format string to a regex pattern.

    Supports C standard datetime format codes including:
    %Y, %y, %m, %d, %H, %I, %M, %S, %f, %z, %Z, %a, %A, %b, %B, %p, %%

    Returns a regex pattern string with named groups.
    """
    regex = ''
    i = 0
    while i < len(datetime_format):
        if datetime_format[i] == '%' and i + 1 < len(datetime_format):
            code = datetime_format[i:i + 2]
            if code in _DT_FORMAT_CODES:
                regex += _DT_FORMAT_CODES[code]
                i += 2
                continue
        # If not a recognized code, treat as literal
        regex += re.escape(datetime_format[i])
        i += 1
    return regex


def get_regex_for_datetime_format(datetime_format):
    """Convert a strftime-style datetime format to a regex pattern.

    See dt_format_to_regex for details.
    """
    return dt_format_to_regex(datetime_format)


def _parse_tz_offset(tz_str):
    """Parse a timezone offset string like +05:30 or -0530 or +05."""
    from datetime import timedelta, timezone
    if tz_str:
        sign = 1 if tz_str[0] == '+' else -1
        rest = tz_str[1:]
        if ':' in rest:
            parts = rest.split(':')
            hours, minutes = int(parts[0]), int(parts[1])
        elif len(rest) <= 2:
            hours = int(rest)
            minutes = 0
        else:
            hours = int(rest[:-2])
            minutes = int(rest[-2:])
        offset = timedelta(hours=hours, minutes=minutes) * sign
        return timezone(offset)
    return None


def strf_date_convert(string, match, datetime_format):
    """Convert a matched string to a datetime using the given strftime format.

    Args:
        string: The input string.
        match: A regex match object.
        datetime_format: The strftime format string used to match.

    Returns:
        A datetime object.
    """
    from datetime import datetime, timezone, timedelta

    groups = match.groups()
    group_index = 0

    year = None
    month = None
    day = None
    hour = 0
    minute = 0
    second = 0
    microsecond = 0
    tz = None

    i = 0
while i < len(datetime_format):
        if datetime_format[i] == '%' and i + 1 < len(datetime_format):
            code = datetime_format[i:i + 2]
            if code not in _DT_FORMAT_CODES:
                i += 2
                continue
            try:
                val = groups[group_index] if group_index < len(groups) else None
            except IndexError:
                val = None
            if val is not None:
                if code == '%Y':
                    year = int(val)
                elif code == '%y':
                    year = 2000 + int(val)
                elif code == '%m':
                    month = int(val)
                elif code == '%d':
                    day = int(val)
                elif code == '%H':
                    hour = int(val)
                elif code == '%I':
                    hour = int(val)
                elif code == '%M':
                    minute = int(val)
                elif code == '%S':
                    second = int(val)
                elif code == '%f':
                    # variable digit fractional seconds - pad/truncate to 6 digits
                    microsecond = int(val.ljust(6, '0')[:6])
                elif code == '%z':
                    tz = _parse_tz_offset(val)
                elif code == '%Z':
                    # timezone name - cannot reliably map without pytz, skip
                    pass
                elif code == '%p':
                    if val == 'PM' and hour < 12:
                        hour += 12
                    elif val == 'AM' and hour == 12:
                        hour = 0
            group_index += 1
            i += 2
            continue
        i += 1

    if year is not None and month is not None and day is not None:
        return datetime(year, month, day, hour, minute, second, microsecond, tz)
    elif year is not None and month is not None:
        return datetime(year, month, 1, hour, minute, second, microsecond, tz)
    else:
        return datetime(1900, 1, 1, hour, minute, second, microsecond, tz)


